const lines = (t) => t.split('\n').map((l) => l.split(' | ')).filter((p) => p.length >= 5);
// incorpora las tablas v7 a los diccionarios generales
export function applyV7({ UI, TXT_PTCA, KW, SENT, MSG, MSG_RE, CMD_ES, GL, PT, CA }) {
  const pt = [];
  for (const [es, gl, en, ptv, ca] of lines(UI7)) { if (!UI[es] || UI[es][1] === es || UI[es][0] === es) UI[es] = [gl, en]; pt.push(`${es} | ${ptv} | ${ca}`); }
  TXT_PTCA.push('\n' + pt.join('\n') + '\n');
  for (const [en, es, gl, ptv, ca] of lines(SENT7)) { SENT[en] ??= es; GL.SENT_GL[en] ??= gl; PT.SENT[en] ??= ptv; CA.SENT[en] ??= ca; }
  for (const [en, es, gl, ptv, ca] of lines(KW7)) { if (!(en in KW)) KW[en] = es; if (!(en in GL.KW_GL)) GL.KW_GL[en] = gl; if (!(en in PT.KW)) PT.KW[en] = ptv; if (!(en in CA.KW)) CA.KW[en] = ca; }
  for (const [en, es, gl, ptv, ca] of lines(MSG7)) { MSG[en] ??= es; GL.MSG_GL[en] ??= gl; PT.MSG[en] ??= ptv; CA.MSG[en] ??= ca; }
  for (const [re, es, gl, ptv, ca] of MSGRE7) { MSG_RE.push([re, es]); GL.MSG_RE_GL.push([re, gl]); PT.MSG_RE.push([re, ptv]); CA.MSG_RE.push([re, ca]); }
  for (const [en, [es, gl, ptv, ca]] of Object.entries(CMD7)) {
    if (!CMD_ES[es]) CMD_ES[es] = en;
    if (!GL.CMD_GL[gl]) GL.CMD_GL[gl] = en;
    if (!PT.CMD[ptv]) PT.CMD[ptv] = en;
    if (!CA.CMD[ca]) CA.CMD[ca] = en;
  }
}
